import{_ as p,a0 as s,w as l,s as i,ao as a,I as r,a1 as n,A as u,x as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"如何從Ubuntu的聲音菜單中移除音樂播放器 | LCTT x X-CMD","titleTemplate":false,"description":"如何從Ubuntu的聲音菜單中移除音樂播放器 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何從Ubuntu的聲音菜單中移除音樂播放器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何從Ubuntu的聲音菜單中移除音樂播放器 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141112 How to Remove Music Players from Ubuntu Sound Menu","title":"如何從Ubuntu的聲音菜單中移除音樂播放器","tag":"201412","desc":""},"relativePath":"201412/20141112 How to Remove Music Players from Ubuntu Sound Menu.md","filePath":"[post].md"}'),d={name:"201412/20141112 How to Remove Music Players from Ubuntu Sound Menu.md"};function m(b,t,f,g,w,T){const e=s("Link");return l(),i("div",null,[t[14]||(t[14]=a('<h1 id="如何從ubuntu的聲音菜單中移除音樂播放器" tabindex="-1">如何從Ubuntu的聲音菜單中移除音樂播放器 <a class="header-anchor" href="#如何從ubuntu的聲音菜單中移除音樂播放器" aria-label="Permalink to “如何從Ubuntu的聲音菜單中移除音樂播放器”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/11/music-players.jpg" alt=""></p><p><strong>自從2010年首次出現，Ubuntu 的聲音菜單已經被證明是Unity 桌面上的最流行的獨有特性之一。</strong></p><p>把音樂播放器與音量控制程序集成到一個標準的界面裏是一種看起來很聰明的做法，這樣就不用到處找聲音相關的各種程序。人們不禁要問，為什麼其它操作系統沒有效仿這種做法！</p><h4 id="臃腫" tabindex="-1">臃腫 <a class="header-anchor" href="#臃腫" aria-label="Permalink to “臃腫”">​</a></h4><p>儘管它看起來很方便，但是這個小應用當前存在一個問題：很多播放器都堆在一起，像一個組合音響一樣。也許你用得着，但是你安裝的所有的媒體播放器都擠在這裏，這會讓人看着很累贅和反感。</p><p>我將要打賭，當你讀到這裏時，一定發現上面的截圖看起來很熟悉！不要擔心，<strong>dconf-editor</strong>可以解決它。</p><h3 id="從ubuntu-聲音菜單中移除播放器" tabindex="-1">從Ubuntu 聲音菜單中移除播放器 <a class="header-anchor" href="#從ubuntu-聲音菜單中移除播放器" aria-label="Permalink to “從Ubuntu 聲音菜單中移除播放器”">​</a></h3><h4 id="第一部分-基礎知識" tabindex="-1">第一部分: 基礎知識 <a class="header-anchor" href="#第一部分-基礎知識" aria-label="Permalink to “第一部分: 基礎知識”">​</a></h4><p>最快速和最簡單地從聲音菜單中移除播放器的方法就是卸載相關的應用程序。但這是極端的方式，我的意思是指你也許想要保留應用程序，但是不需要它集成到菜單裏面。</p><p>只刪除播放器但是保留我們需要的應用程序，我們用到一個看起來令人驚訝的工具叫“dconf-editor”。</p><p>你可能已經安裝了，如果沒有安裝的話，那麼你從Ubuntu軟件中心找出。</p>',12)),r("ul",null,[r("li",null,[n(e,{href:"apt://dconf-editor"},{default:u(()=>[...t[0]||(t[0]=[o("在Ubuntu中點擊安裝Dconf-Editor",-1)])]),_:1})])]),t[15]||(t[15]=a(`<p>一旦安裝完畢，找到Unity Dash並打開。打開的時候不要驚慌；你沒有到2002年，它確實是這種古老的樣子。</p><p>使用右側菜單欄，你需要從導航到 com &gt; canonical &gt; indicator &gt; sound.下面的面板將會出現。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/11/dconf-editor.jpg" alt=""></p><p>雙擊“interested-media-players”旁的閉括號，並刪除你希望從聲音菜單裏移除掉的播放器，但需要保留方括號中，且不要刪除任何需要保留的逗號或者單引號。</p><p>舉個例子，我移除掉這些</p><p>‘<strong>rhythmbox.desktop</strong>’, ‘<strong>pithos.desktop</strong>’, ‘<strong>clementine.desktop</strong>’,</p><p>這樣就好留了一行如下：</p><pre><code>[&#39;tomahawk.desktop&#39;]
</code></pre><p>現在，當我再打開聲音菜單時，我只看到Tomahawk:</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/11/music-players-2.jpg" alt=""></p><h4 id="第二部分-黑名單" tabindex="-1">第二部分：黑名單 <a class="header-anchor" href="#第二部分-黑名單" aria-label="Permalink to “第二部分：黑名單”">​</a></h4><p>等等！還不能關閉dconf-editor。儘管上面的步驟看起來把事情處理得乾淨利落，但是一些播放器在打開時會立即重新加載到聲音菜單。為了避免重複這個過程，將它們添加到<strong>blacklisted-media-player</strong>中。</p><p>記得每個在括號裏的播放器都用逗號分隔多個條目。他們也必須在方括號內，所以在退出之前請務必仔細檢查。</p><p>最終結果如下：</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/10/from-to-.jpg" alt=""></p><hr>`,16)),r("p",null,[t[2]||(t[2]=o("via: ",-1)),n(e,{href:"http://www.omgubuntu.co.uk/2014/11/remove-players-ubuntu-sound-menu"},{default:u(()=>[...t[1]||(t[1]=[o("http://www.omgubuntu.co.uk/2014/11/remove-players-ubuntu-sound-menu",-1)])]),_:1})]),r("p",null,[t[6]||(t[6]=o("作者：",-1)),n(e,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:u(()=>[...t[3]||(t[3]=[o("Joey-Elijah Sneddon",-1)])]),_:1}),t[7]||(t[7]=o(" 譯者：",-1)),n(e,{href:"https://github.com/%E8%AD%AF%E8%80%85ID"},{default:u(()=>[...t[4]||(t[4]=[o("disylee",-1)])]),_:1}),t[8]||(t[8]=o(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:u(()=>[...t[5]||(t[5]=[o("wxy",-1)])]),_:1})]),r("p",null,[t[11]||(t[11]=o("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[9]||(t[9]=[o("LCTT",-1)])]),_:1}),t[12]||(t[12]=o(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:u(()=>[...t[10]||(t[10]=[o("Linux中國",-1)])]),_:1}),t[13]||(t[13]=o(" 榮譽推出",-1))])])}const x=p(d,[["render",m]]);export{_ as __pageData,x as default};
